window.SWO_C=(window.SWO_C||[]);SWO_C.push("<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Study with OR</title>\n<link rel=\"icon\" type=\"image/png\" href=\"data:image/png;base64,\">\n<style>\n  * { margin:0; padding:0; box-sizing:border-box; }\n  html,body { width:100%; height:100%; overflow:hidden; background:#0e1a16;\n    font-family:'Segoe UI', Tahoma, 'Noto Kufi Arabic', sans-serif; }\n  #stage { position:relative; width:100vw; height:100vh; overflow:hidden; user-select:none; }\n\n  /* ---------- الغرفة ---------- */\n  #wall { position:absolute; inset:0 0 29.7% 0; z-index:0;\n    background:\n      radial-gradient(120% 90% at 50% 0%, rgba(70,110,95,.25), transparent 60%),\n      linear-gradient(180deg, #202f2a 0%, #1c2b26 45%, #18251f 100%);\n  }\n  .panel-line { position:absolute; top:6%; bottom:6%; width:24%;\n    border:2px solid rgba(160,220,195,.06); border-radius:6px; }\n  #baseboard { position:absolute; left:0; right:0; top:60.2%; height:2.8%; z-index:1;\n    background:linear-gradient(180deg,#0d1714,#132019); }\n  #desk { position:absolute; left:0; right:0; top:70.3%; bottom:0; z-index:1;\n    background: linear-gradient(180deg, rgba(10,20,15,.55), transparent 30%), url(data:image/jpeg;base64,) center/cover no-repeat;\n    box-shadow: inset 0 10px 20px -10px rgba(0,0,0,.35);\n  }\n  #restTint { position:absolute; inset:0; z-index:1; pointer-events:none;\n    background:linear-gradient(180deg, rgba(74,56,116,.42), rgba(52,38,88,.38));\n    opacity:0; transition:opacity .8s; }\n  body.rest #restTint { opacity:1; }\n\n  .prop { position:absolute; z-index:2; pointer-events:none; }\n  .prop img { width:100%; height:100%; display:block; }\n\n  /* ---------- اللافتة ---------- */\n  #ropes { position:absolute; top:0; left:0; right:0; height:2.4vh; z-index:3; pointer-events:none; }\n  .rope { position:absolute; top:0; height:100%; border-right:3px dotted #9b7d55; }\n  #sign { position:absolute; top:2.4vh; left:50%; transform:translateX(-50%); z-index:3;\n    direction:ltr; padding:1.1vh 4.5vw; border-radius:14px;\n    background:\n      repeating-linear-gradient(180deg, transparent 0 calc(50% - 1px), rgba(60,40,20,.55) calc(50% - 1px) calc(50% + 1px), transparent calc(50% + 1px)),\n      linear-gradient(180deg,#9c7a52,#7d5c3a 55%,#6b4c2f);\n    border:3px solid #54391f; box-shadow:0 8px 18px rgba(0,0,0,.5), inset 0 2px 3px rgba(255,230,190,.25);\n    color:#fff; font-weight:800; font-size:3.4vh; letter-spacing:.5px;\n    text-shadow:0 2px 3px rgba(60,35,10,.8); white-space:nowrap; }\n\n  #logo { position:absolute; top:1.6vh; left:1.2vw; width:3.4vw; max-width:52px; z-index:6;\n    border-radius:10px; opacity:.88; box-shadow:0 2px 8px rgba(0,0,0,.4); }\n\n  /* ---------- البراويز ---------- */\n  .frame { position:absolute; z-index:2; padding:.55vh .35vw; cursor:pointer;\n    background:linear-gradient(160deg,#8a6539,#5d3f22);\n    border-radius:4px; border:1px solid #3f2a14;\n    box-shadow:0 7px 16px rgba(0,0,0,.55), inset 0 0 0 2px #a07a48;\n    transition:transform .25s; }\n  .frame:hover { transform:scale(1.045); }\n  .frame img { width:100%; height:100%; object-fit:cover; display:block; border-radius:2px;\n    box-shadow:inset 0 0 0 2px rgba(0,0,0,.35); }\n\n  /* ---------- سبورة المهام ---------- */\n  #board { position:absolute; left:73.5%; top:35%; width:13%; height:22%; z-index:2;\n    background:linear-gradient(170deg,#cfc3ec,#b7a8de);\n    border:3px solid #8d7bb8; border-radius:14px;\n    box-shadow:0 8px 16px rgba(0,0,0,.45), inset 0 2px 4px rgba(255,255,255,.5);\n    color:#3a3350; padding:1.4vh .7vw; }\n  #board h3 { font-size:1.9vh; text-align:center; margin-bottom:1vh;\n    border-bottom:2px solid rgba(58,51,80,.35); padding-bottom:.6vh; }\n  .todo { display:flex; align-items:center; gap:.5vw; font-size:1.65vh; padding:.5vh .2vw;\n    cursor:pointer; border-radius:8px; }\n  .todo:hover { background:rgba(255,255,255,.25); }\n  .todo .box { width:1.6vh; height:1.6vh; min-width:14px; min-height:14px; border:2px solid #6a5d94;\n    border-radius:4px; display:inline-flex; align-items:center; justify-content:center;\n    background:#fff; font-size:1.4vh; color:#3f7d5a; font-weight:900; }\n  .todo.done .txt { text-decoration:line-through; opacity:.55; }\n\n  /* ---------- الشخصيات ---------- */\n  .char { position:absolute; z-index:4; pointer-events:none; transition:opacity .6s; }\n  .char img { width:100%; height:100%; object-fit:contain; display:block;\n    filter:drop-shadow(0 6px 10px rgba(0,0,0,.35)); }\n  .char .inner { width:100%; height:100%; }\n  .anim .inner { animation:breathe 3.2s ease-in-out infinite; transform-origin:50% 100%; }\n  @keyframes breathe { 0%,100%{transform:scaleY(1) translateY(0)} 50%{transform:scaleY(1.018) translateY(-.4%)} }\n  .frozen .inner { animation-play-state:paused; }\n\n  /* ---------- العجلة ---------- */\n  #wheelWrap { position:absolute; left:31.5%; top:16.5%; width:32%; height:57%; z-index:3; }\n  #wheel { width:100%; height:100%; cursor:pointer; }\n  #pointer { position:absolute; top:-2.2%; left:50%; transform:translateX(-50%); z-index:4;\n    width:0; height:0; border-left:1.6vh solid transparent; border-right:1.6vh solid transparent;\n    border-top:3.4vh solid #7fc8bc; filter:drop-shadow(0 3px 3px rgba(0,0,0,.5)); }\n  body.rest #pointer { border-top-color:#b8a9e0; }\n  #spinBtn { position:absolute; left:50%; top:50%; transform:translate(-50%,-50%); z-index:5;\n    width:11.5vh; height:11.5vh; border-radius:50%; border:4px solid #54391f;\n    background:radial-gradient(circle at 35% 30%, #a8815a, #6b4c2f 75%);\n    color:#fff; font-size:2.5vh; font-weight:800; cursor:pointer; font-family:inherit;\n    box-shadow:0 6px 14px rgba(0,0,0,.5), inset 0 2px 4px rgba(255,230,190,.3);\n    text-shadow:0 2px 2px rgba(60,35,10,.8); transition:transform .15s; }\n  #spinBtn:hover { transform:translate(-50%,-50%) scale(1.07); }\n  #spinBtn:disabled { opacity:.55; cursor:default; transform:translate(-50%,-50%); }\n\n  #editWrap { position:absolute; top:74.6%; left:50%; transform:translateX(-50%); z-index:6;\n    text-align:center; }\n  #editToggle { background:rgba(20,35,30,.75); color:#bfe3d8; border:1px solid rgba(127,200,187,.4);\n    border-radius:20px; padding:.7vh 1.4vw; font-size:1.7vh; cursor:pointer; font-family:inherit; }\n  #editPanel { display:none; margin-top:1vh; background:rgba(16,28,24,.92); border:1px solid rgba(127,200,187,.35);\n    border-radius:14px; padding:1.2vh 1vw; direction:rtl; }\n  #editPanel.open { display:block; }\n  #editPanel input { width:4.2vw; max-width:64px; margin:0 .25vw; padding:.6vh .3vw; text-align:center;\n    font-size:1.8vh; border-radius:8px; border:1px solid #3f6a5c; background:#0f1e19; color:#dff3ec;\n    font-family:inherit; }\n  #editApply { margin-top:1vh; background:#2e6b57; color:#fff; border:none; border-radius:10px;\n    padding:.8vh 2.2vw; font-size:1.8vh; cursor:pointer; font-family:inherit; }\n\n  /* ---------- التايمر ---------- */\n  #timerPanel { position:absolute; left:24%; top:33%; width:46%; height:34%; z-index:7;\n    background:linear-gradient(165deg, rgba(22,42,36,.88), rgba(15,28,24,.9));\n    border:2.5px solid rgba(127,200,187,.45); border-radius:36px;\n    box-shadow:0 18px 44px rgba(0,0,0,.6), inset 0 1px 0 rgba(180,240,225,.15);\n    backdrop-filter:blur(6px);\n    display:flex; flex-direction:column; align-items:center; justify-content:center; gap:1vh; }\n  body.rest #timerPanel { border-color:rgba(184,169,224,.5); }\n  #timerLabel { font-size:2.4vh; color:#9fd8cb; font-weight:700; }\n  body.rest #timerLabel { color:#cfc3ec; }\n  #timerDigits { font-size:11vh; font-weight:800; color:#eafff7; line-height:1;\n    font-variant-numeric:tabular-nums; direction:ltr; letter-spacing:.3vh;\n    text-shadow:0 0 24px rgba(127,200,187,.35); }\n  body.rest #timerDigits { color:#f3efff; text-shadow:0 0 24px rgba(184,169,224,.4); }\n  #progressTrack { width:70%; height:.9vh; background:rgba(255,255,255,.12); border-radius:99px; overflow:hidden; }\n  #progressBar { height:100%; width:100%; background:linear-gradient(90deg,#7fc8bc,#3e9c86);\n    border-radius:99px; transition:width .3s linear; }\n  body.rest #progressBar { background:linear-gradient(90deg,#cfc3ec,#8d7bb8); }\n  #timerBtns { display:flex; gap:1vw; margin-top:.6vh; }\n  .tbtn { font-family:inherit; cursor:pointer; border-radius:14px; font-size:2.1vh; font-weight:700;\n    padding:1.2vh 2.4vw; border:none; transition:transform .12s; }\n  .tbtn:hover { transform:scale(1.05); }\n  #startBtn { background:linear-gradient(180deg,#3e9c86,#2e6b57); color:#fff;\n    box-shadow:0 6px 14px rgba(20,80,65,.5); }\n  body.rest #startBtn { background:linear-gradient(180deg,#8d7bb8,#5a4e85); }\n  #pauseBtn, #resetBtn { background:rgba(255,255,255,.1); color:#d5efe7; border:1.5px solid rgba(127,200,187,.4); }\n  body.rest #pauseBtn, body.rest #resetBtn { color:#e4dcf7; border-color:rgba(184,169,224,.4); }\n\n  /* ---------- عام ---------- */\n  #backBtn { position:absolute; top:1.8vh; right:1.2vw; z-index:8;\n    background:rgba(20,35,30,.8); color:#cfe9e0; border:1px solid rgba(127,200,187,.4);\n    border-radius:20px; padding:.8vh 1.4vw; font-size:1.8vh; cursor:pointer; font-family:inherit; }\n  #toast { position:absolute; top:14vh; left:50%; transform:translateX(-50%) translateY(-8px); z-index:9;\n    background:rgba(16,28,24,.92); color:#dff3ec; border:1px solid rgba(127,200,187,.5);\n    padding:1vh 2.4vw; border-radius:99px; font-size:2.2vh; font-weight:700;\n    opacity:0; pointer-events:none; transition:opacity .4s, transform .4s; }\n  #toast.show { opacity:1; transform:translateX(-50%) translateY(0); }\n\n  #soundCtl { position:absolute; bottom:1.6vh; left:1.2vw; z-index:8; display:flex; gap:1.4vw;\n    align-items:center; background:rgba(16,28,24,.8); border:1px solid rgba(127,200,187,.3);\n    border-radius:99px; padding:.9vh 1.2vw; direction:ltr; }\n  .sld { display:flex; align-items:center; gap:.45vw; font-size:1.9vh; }\n  .sld input { width:5.5vw; max-width:90px; accent-color:#7fc8bc; cursor:pointer; }\n\n  #lightbox { position:fixed; inset:0; z-index:20; background:rgba(6,12,10,.9);\n    display:none; align-items:center; justify-content:center; cursor:zoom-out; }\n  #lightbox.open { display:flex; }\n  #lightbox img { max-width:88vw; max-height:88vh; border-radius:10px;\n    border:10px solid #6b4c2f; box-shadow:0 24px 70px rgba(0,0,0,.8); }\n\n  .page { position:absolute; inset:0; opacity:0; visibility:hidden;\n    transition:opacity .55s ease, visibility .55s; }\n  .page.on { opacity:1; visibility:visible; }\n\n  #vignette { position:absolute; inset:0; z-index:6; pointer-events:none;\n    background:radial-gradient(130% 105% at 50% 42%, transparent 55%, rgba(4,10,8,.5) 100%); }\n  /* ===== intro ===== */\n  #intro { position:fixed; inset:0; z-index:99; display:flex; align-items:center; justify-content:center;\n    background:linear-gradient(180deg, rgb(21,52,37) 0%, rgb(17,47,33) 50%, rgb(14,44,29) 100%); cursor:pointer; }\n  #introVideo { position:absolute; inset:0; width:100%; height:100%; object-fit:contain; }\n  #intro::after { content:''; position:absolute; inset:0; pointer-events:none;\n    background:radial-gradient(115% 95% at 50% 50%, transparent 58%, rgba(5,12,9,.5) 100%); }\n  #introTap { position:absolute; left:50%; bottom:11vh; transform:translateX(-50%); z-index:2;\n    background:rgba(14,32,24,.82); color:#f5e9c9; border:1.5px solid rgba(240,225,180,.55);\n    border-radius:99px; padding:1.3vh 5vw; font-size:2.4vh; font-weight:700; cursor:pointer;\n    font-family:inherit; animation:tapPulse 1.6s ease-in-out infinite; }\n  @keyframes tapPulse { 0%,100%{transform:translateX(-50%) scale(1)} 50%{transform:translateX(-50%) scale(1.07)} }\n  #intro.leave { transition:opacity .85s ease; opacity:0; pointer-events:none; }\n\n  /* ===== الموبايل ===== */\n  @media (orientation: portrait), (max-width: 760px) {\n    #sign { font-size:4.4vw; padding:.8vh 4.5vw; top:1vh; }\n    #logo { width:7vw; }\n    .frame[data-slot=\"b\"], .frame[data-slot=\"c\"], .frame[data-slot=\"d\"], .frame[data-slot=\"e\"] { display:none; }\n    .frame[data-slot=\"a\"] { left:3vw !important; top:4.5vh !important; width:24vw !important; height:10vh !important; }\n    #wheelWrap { left:50%; transform:translateX(-50%); top:15vh; width:min(92vw,50vh); height:min(92vw,50vh); }\n    #board { left:50%; transform:translateX(-50%); top:58vh; width:46vw; height:15vh; padding:.8vh 2vw; overflow:hidden; }\n    #board h3 { font-size:3.6vw; margin-bottom:.3vh; padding-bottom:.3vh; }\n    .todo { font-size:3.1vw; padding:.3vh .2vw; }\n    #editWrap { top:auto; bottom:11vh; }\n    #editPanel { max-width:94vw; }\n    #editPanel input { width:10vw; }\n    #timerPanel { left:5vw; top:22vh; width:90vw; height:36vh; border-radius:22px; }\n    #timerDigits { font-size:9vh; }\n    #timerLabel { font-size:2.8vw; }\n    .tbtn { font-size:2.4vh; padding:1.3vh 4vw; }\n    #soundCtl { left:50%; transform:translateX(-50%); bottom:1vh; padding:.7vh 2.5vw; gap:3vw; }\n    .sld { font-size:2.4vh; }\n    .sld input { width:14vw; max-width:none; }\n    #toast { font-size:2vh; top:12vh; }\n    #backBtn { font-size:2.2vh; }\n  }\n</style>\n</head>\n<body>\n  <div id=\"intro\" aria-hidden=\"true\">\n    <video id=\"introVideo\" playsinline preload=\"auto\" data-src=\"data:video/mp4;base64,");
